body {
  font-family: Arial, sans-serif;
  text-align: center;
  background: #f4efff;
  color: #33274e;
}

.maschine {
  max-width: 360px;
  margin: 35px auto;
  padding: 20px;
  background: #43356c;
  color: #fff6cf;
  border: 5px solid #f3c460;
  border-radius: 24px;
}

.slots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin: 18px 0;
}

.slot {
  width: 75px;
  padding: 14px 0;
  background: white;
  color: #43356c;
  border-radius: 10px;
  font-size: 2rem;
  font-weight: bold;
}

button {
  margin: 5px;
  padding: 10px 15px;
  background: #f3c460;
  color: #33274e;
  border: 0;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
}
button:disabled { opacity: .5; cursor: wait; }

.gewonnen { animation: jubeln .6s ease-in-out 2; }

.slots.dreht { animation: drehen .6s ease-in-out; }

@keyframes drehen {
  0%, 100% { transform: translateY(0); opacity: 1; }
  25% { transform: translateY(12px); opacity: .25; }
  50% { transform: translateY(-12px); opacity: .4; }
  75% { transform: translateY(8px); opacity: .25; }
}

@keyframes jubeln {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.06); }
}

